#include "instrument_screens.h"
#include <math.h>
#include <stdlib.h>
#include <string.h>
#include "horizon_renderer.h"

#define BLACK 0x0000
#define WHITE 0xFFFF
#define RED 0xF800
#define YELLOW 0xFFE0
#define GREY 0x4208
#define DARK_GREY 0x2104
#define GREEN 0x07E0

static void px(uint16_t*f,int w,int h,int x,int y,uint16_t c){if((unsigned)x<(unsigned)w&&(unsigned)y<(unsigned)h)f[y*w+x]=c;}
static void ln(uint16_t*f,int w,int h,int x0,int y0,int x1,int y1,uint16_t c){int dx=abs(x1-x0),sx=x0<x1?1:-1,dy=-abs(y1-y0),sy=y0<y1?1:-1,e=dx+dy;for(;;){px(f,w,h,x0,y0,c);if(x0==x1&&y0==y1)break;int e2=2*e;if(e2>=dy){e+=dy;x0+=sx;}if(e2<=dx){e+=dx;y0+=sy;}}}
static void thick_ln(uint16_t*f,int w,int h,int x0,int y0,int x1,int y1,uint16_t c,int t){for(int d=-(t/2);d<=t/2;d++){ln(f,w,h,x0+d,y0,x1+d,y1,c);ln(f,w,h,x0,y0+d,x1,y1+d,c);}}
static void fill(uint16_t*f,int w,int h,uint16_t c){for(int i=0;i<w*h;i++)f[i]=c;}
static void rect(uint16_t*f,int w,int h,int x0,int y0,int x1,int y1,uint16_t c){for(int y=y0;y<=y1;y++)for(int x=x0;x<=x1;x++)px(f,w,h,x,y,c);}
static void circ(uint16_t*f,int w,int h,int cx,int cy,int r,uint16_t c){int x=r,y=0,e=0;while(x>=y){int p[8][2]={{x,y},{y,x},{-y,x},{-x,y},{-x,-y},{-y,-x},{y,-x},{x,-y}};for(int i=0;i<8;i++)px(f,w,h,cx+p[i][0],cy+p[i][1],c);y++;if(e<=0)e+=2*y+1;if(e>0){x--;e-=2*x+1;}}}
static void radial(uint16_t*f,int w,int h,float deg,int r0,int r1,uint16_t c){float a=(deg-90)*M_PI/180.0f;int cx=w/2,cy=h/2;ln(f,w,h,cx+(int)(cosf(a)*r0),cy+(int)(sinf(a)*r0),cx+(int)(cosf(a)*r1),cy+(int)(sinf(a)*r1),c);}
static void hand(uint16_t*f,int w,int h,float deg,int r,uint16_t c,int t){float a=(deg-90)*M_PI/180.0f;int cx=w/2,cy=h/2;int x=cx+(int)(cosf(a)*r),y=cy+(int)(sinf(a)*r);thick_ln(f,w,h,cx,cy,x,y,c,t);}
static void box(uint16_t*f,int w,int h,int x0,int y0,int x1,int y1,uint16_t c){ln(f,w,h,x0,y0,x1,y0,c);ln(f,w,h,x1,y0,x1,y1,c);ln(f,w,h,x1,y1,x0,y1,c);ln(f,w,h,x0,y1,x0,y0,c);}
static void invalid_x(uint16_t*f,int w,int h,int x0,int y0,int x1,int y1){for(int d=-3;d<=3;d++){ln(f,w,h,x0+d,y0,x1+d,y1,RED);ln(f,w,h,x1+d,y0,x0+d,y1,RED);}}
static void invalid(uint16_t*f,int w,int h){invalid_x(f,w,h,95,95,w-96,h-96);}
static const char *glyph(char c){switch(c){case 'A':return"010101111101101";case 'B':return"110101110101110";case 'C':return"011100100100011";case 'D':return"110101101101110";case 'E':return"111100110100111";case 'F':return"111100110100100";case 'G':return"011100101101011";case 'H':return"101101111101101";case 'I':return"111010010010111";case 'K':return"101101110101101";case 'L':return"100100100100111";case 'M':return"101111111101101";case 'N':return"101111111111101";case 'O':return"010101101101010";case 'P':return"110101110100100";case 'Q':return"010101101111011";case 'R':return"110101110101101";case 'S':return"011100010001110";case 'T':return"111010010010010";case 'U':return"101101101101111";case 'V':return"101101101101010";case 'W':return"101101111111101";case 'Y':return"101101010010010";case '+':return"000010111010000";case '-':return"000000111000000";case '/':return"001001010100100";case ':':return"000010000010000";case '0':return"111101101101111";case '1':return"010110010010111";case '2':return"110001111100111";case '3':return"110001111001110";case '4':return"101101111001001";case '5':return"111100110001110";case '6':return"011100111101111";case '7':return"111001010010010";case '8':return"111101111101111";case '9':return"111101111001110";default:return"000000000000000";}}
static void text(uint16_t*f,int w,int h,int x,int y,const char*s,int scale,uint16_t c){for(;*s;s++,x+=4*scale){const char*g=glyph(*s);for(int yy=0;yy<5;yy++)for(int xx=0;xx<3;xx++)if(g[yy*3+xx]=='1')rect(f,w,h,x+xx*scale,y+yy*scale,x+(xx+1)*scale-1,y+(yy+1)*scale-1,c);}}
static void num(uint16_t*f,int w,int h,int x,int y,int n,int scale,uint16_t c){char b[12];int p=11;b[p]=0;if(n==0)b[--p]='0';else{bool neg=n<0;if(neg)n=-n;while(n&&p)b[--p]=(char)('0'+n%10),n/=10;if(neg)b[--p]='-';}text(f,w,h,x,y,&b[p],scale,c);}
static void sim_marker(uint16_t*f,int w,int h){rect(f,w,h,194,h-38,286,h-7,RED);box(f,w,h,192,h-40,288,h-5,BLACK);text(f,w,h,211,h-32,"SIM",4,WHITE);}
static void instrument_bezel(uint16_t*f,int w,int h){int cx=w/2,cy=h/2;for(int r=239;r>=224;r--)circ(f,w,h,cx,cy,r,(r>232)?DARK_GREY:BLACK);for(int k=0;k<3;k++)circ(f,w,h,cx,cy,222-k,WHITE);for(int k=0;k<3;k++)circ(f,w,h,cx,cy,216-k,GREY);}
static void alt_number(uint16_t*f,int w,int h,int value,float deg){float a=(deg-90)*M_PI/180.0f;int r=162;int x=w/2+(int)(cosf(a)*r)-9;int y=h/2+(int)(sinf(a)*r)-10;num(f,w,h,x,y,value,4,WHITE);}
static void altitude_hatching(uint16_t*f,int w,int h,int altitude_ft){if(altitude_ft<=10000)return;int excess=altitude_ft-10000;if(excess>1000)excess=1000;const int x0=196,x1=284,y0=190,y1=236;int height=y1-y0+1;int reveal=(height*excess)/1000;if(reveal<3)reveal=3;int top=y1-reveal+1;rect(f,w,h,x0,top,x1,y1,BLACK);for(int x=x0-48;x<=x1+48;x+=14){for(int d=0;d<5;d++){int sx=x+d,sy=y1,ex=sx+reveal,ey=top;if(ex<x0||sx>x1)continue;if(sx<x0){sy-=x0-sx;sx=x0;}if(ex>x1){ey+=ex-x1;ex=x1;}if(sy<top)sy=top;if(ey>y1)ey=y1;ln(f,w,h,sx,sy,ex,ey,WHITE);}}box(f,w,h,x0,y0,x1,y1,WHITE);}
static void alt_test_overlay(uint16_t*f,int w,int h,const instrument_data_t*d){if(!d->test_overlay)return;rect(f,w,h,96,78,384,136,BLACK);box(f,w,h,96,78,384,136,WHITE);text(f,w,h,132,85,"TEST MODE - ALT",2,YELLOW);num(f,w,h,116,108,d->test_index,2,WHITE);text(f,w,h,136,108,"/",2,WHITE);num(f,w,h,148,108,d->test_count,2,WHITE);text(f,w,h,180,108,d->test_name?d->test_name:"TEST",2,WHITE);text(f,w,h,184,127,"TIME",1,WHITE);num(f,w,h,208,127,d->test_seconds_left,1,GREEN);text(f,w,h,220,127,"S",1,GREEN);}
static void altimeter(uint16_t*f,int w,int h,const instrument_ui_t*u,const instrument_data_t*d){fill(f,w,h,BLACK);instrument_bezel(f,w,h);int r=205;for(int i=0;i<50;i++){int major=(i%5)==0;radial(f,w,h,i*7.2f,r-(major?28:12),r,WHITE);}for(int n=0;n<10;n++)alt_number(f,w,h,n,n*36.0f);text(f,w,h,204,151,"ALT",3,WHITE);text(f,w,h,208,171,"FEET",2,GREY);if(d->altitude_valid){int a=d->altitude_ft<0?0:d->altitude_ft;altitude_hatching(f,w,h,a);hand(f,w,h,(a%1000)*.36f,142,WHITE,3);hand(f,w,h,(a%10000)*.036f,105,WHITE,5);hand(f,w,h,(a%100000)*.0036f,70,WHITE,7);for(int k=0;k<8;k++)circ(f,w,h,w/2,h/2,k,WHITE);rect(f,w,h,154,292,326,337,BLACK);box(f,w,h,154,292,326,337,WHITE);num(f,w,h,174,302,a,4,GREEN);}else{rect(f,w,h,120,187,360,286,BLACK);box(f,w,h,120,187,360,286,RED);invalid_x(f,w,h,132,195,348,278);rect(f,w,h,142,211,338,255,BLACK);text(f,w,h,151,220,"ALT FAIL",5,RED);}rect(f,w,h,148,347,332,398,BLACK);box(f,w,h,148,347,332,398,u->settings_active?YELLOW:WHITE);text(f,w,h,164,355,"QNH",2,u->settings_active?YELLOW:WHITE);num(f,w,h,218,352,u->qnh_hpa,3,GREEN);text(f,w,h,274,365,"HPA",1,WHITE);text(f,w,h,178,383,"KOLLSMAN",1,GREY);alt_test_overlay(f,w,h,d);}
static void compass(uint16_t*f,int w,int h,const instrument_ui_t*u,const instrument_data_t*d){fill(f,w,h,BLACK);int r=w/2-25;for(int k=0;k<3;k++)circ(f,w,h,w/2,h/2,r-k,WHITE);float hdg=d->heading_valid?(float)d->heading_deg:0.0f;for(int i=0;i<72;i++){float bearing=i*5.0f-hdg;radial(f,w,h,bearing,r-(i%2?10:(i%6?18:30)),r,WHITE);}ln(f,w,h,w/2,18,w/2-13,48,YELLOW);ln(f,w,h,w/2,18,w/2+13,48,YELLOW);ln(f,w,h,w/2-13,48,w/2+13,48,YELLOW);ln(f,w,h,w/2,170,w/2,310,YELLOW);ln(f,w,h,165,245,315,245,YELLOW);ln(f,w,h,205,305,w/2,280,YELLOW);ln(f,w,h,275,305,w/2,280,YELLOW);radial(f,w,h,(float)u->heading_bug_deg-hdg,r-38,r-8,YELLOW);if(!d->heading_valid)invalid(f,w,h);if(u->settings_active)for(int k=0;k<2;k++)circ(f,w,h,w/2,h/2,r-8-k,YELLOW);}
static void test_overlay(uint16_t*f,int w,int h,const instrument_data_t*d){if(!d->test_overlay)return;rect(f,w,h,103,94,377,154,BLACK);box(f,w,h,103,94,377,154,WHITE);text(f,w,h,126,101,"TEST MODE - ATTITUDE",2,YELLOW);num(f,w,h,126,124,d->test_index,2,WHITE);text(f,w,h,146,124,"/",2,WHITE);num(f,w,h,158,124,d->test_count,2,WHITE);text(f,w,h,190,124,d->test_name?d->test_name:"TEST",2,WHITE);text(f,w,h,190,143,"TIME",1,WHITE);num(f,w,h,214,143,d->test_seconds_left,1,GREEN);text(f,w,h,226,143,"S",1,GREEN);}
static void pfd_bezel(uint16_t*f,int w,int h){int cx=w/2,cy=h/2;for(int r=239;r>=222;r--)circ(f,w,h,cx,cy,r,(r>232)?DARK_GREY:BLACK);for(int k=0;k<3;k++)circ(f,w,h,cx,cy,221-k,WHITE);for(int k=0;k<3;k++)circ(f,w,h,cx,cy,215-k,GREY);static const int marks[]={-60,-45,-30,-20,-10,0,10,20,30,45,60};for(unsigned i=0;i<sizeof(marks)/sizeof(marks[0]);i++){int a=marks[i],len=(a==0||abs(a)==30||abs(a)==60)?24:14;radial(f,w,h,(float)a,190,190+len,WHITE);}ln(f,w,h,cx,31,cx-10,52,WHITE);ln(f,w,h,cx,31,cx+10,52,WHITE);ln(f,w,h,cx-10,52,cx+10,52,WHITE);}
static void pfd_data(uint16_t*f,int w,int h,const instrument_data_t*d){rect(f,w,h,358,177,462,283,BLACK);box(f,w,h,358,177,462,283,d->altitude_valid?WHITE:RED);text(f,w,h,382,188,"ALT",2,WHITE);if(d->altitude_valid)num(f,w,h,377,226,d->altitude_ft,3,GREEN);else invalid_x(f,w,h,368,204,452,270);rect(f,w,h,166,371,314,421,BLACK);box(f,w,h,166,371,314,421,d->heading_valid?WHITE:RED);text(f,w,h,211,378,"HDG",2,WHITE);if(d->heading_valid)num(f,w,h,210,397,d->heading_deg,3,GREEN);else invalid_x(f,w,h,176,380,304,413);}
static void pfd(uint16_t*f,int w,int h,const instrument_ui_t*u,const instrument_data_t*d){horizon_render(f,w,h,d->pitch_deg,d->roll_deg);pfd_bezel(f,w,h);pfd_data(f,w,h,d);if(!d->attitude_valid){rect(f,w,h,125,190,355,286,BLACK);box(f,w,h,125,190,355,286,RED);text(f,w,h,159,216,"ATT FAIL",5,RED);invalid_x(f,w,h,138,198,342,278);}if(u->settings_active)box(f,w,h,155,425,325,458,YELLOW);test_overlay(f,w,h,d);}
void instrument_render(uint16_t*f,int w,int h,const instrument_ui_t*u,const instrument_data_t*d){switch(u->panel){case PANEL_HORIZON:pfd(f,w,h,u,d);break;case PANEL_ALTIMETER:altimeter(f,w,h,u,d);break;case PANEL_COMPASS:compass(f,w,h,u,d);break;default:fill(f,w,h,BLACK);}if(d->simulated)sim_marker(f,w,h);}
